// ==============================================================================
// MOTOR DE EXTRACCIÓN DUX & LIQUIDACIÓN COMERCIAL NAZARIA (MASTER V2.8)
// ==============================================================================

const DUX_TOKEN = 'vmkdwI9GaPx96GigvTpUI4gjBFAnQoGyDKRV1HuWO4LNZ3HOyvkA9YtxFVbZSNYo';
const ENTERPRISE_ID = 2224;

// Determinar rango de fechas: mes anterior completo
const now = new Date();
let year = now.getFullYear();
let month = now.getMonth(); // 0 a 11 (mes anterior si hoy es día 1)
if (month === 0) {
  month = 12;
  year = year - 1;
}
const targetPeriod = `${year}-${String(month).padStart(2, '0')}`;
const fDesde = `${year}-${String(month).padStart(2, '0')}-01`;
const lastDay = new Date(year, month, 0).getDate();
const fHasta = `${year}-${String(month).padStart(2, '0')}-${String(lastDay).padStart(2, '0')}`;

// Mapeo oficial de Vendedoras por id_vendedor Dux
const VEND_MAP = {
  // TOM (idSucursal: 2)
  '1705102': { colab_id: 'c-sofi', nombre: 'Sofía Barrientos', rol: 'Encargada', sucursal: 'TOM', hs: 36, isEncargada: true },
  '2907849': { colab_id: 'c-esme', nombre: 'Esme Galarza', rol: 'Semi-Encargada', sucursal: 'TOM', hs: 42, isSemiEncargada: true },
  '19950294': { colab_id: 'c-cande', nombre: 'Candela Almiron', rol: 'Vendedora', sucursal: 'TOM', hs: 24 },
  '19950328': { colab_id: 'c-anto', nombre: 'Antonella Bustamante', rol: 'Vendedora', sucursal: 'TOM', hs: 24 },
  '8662462': { colab_id: 'c-martu', nombre: 'Martina Pinto', rol: 'Vendedora', sucursal: 'TOM', hs: 12 },

  // MASCHWITZ (idSucursal: 3)
  '11956305': { colab_id: 'c-flavia', nombre: 'Flavia Gómez', rol: 'Encargada', sucursal: 'MASCHWITZ', hs: 27.5, isEncargada: true },
  '5171913': { colab_id: 'c-juli', nombre: 'Julieta Vera', rol: 'Vendedora', sucursal: 'MASCHWITZ', hs: 22 },
  '3988841': { colab_id: 'c-cami', nombre: 'Camila Vera', rol: 'Vendedora', sucursal: 'MASCHWITZ', hs: 22 }
};

const delay = ms => new Promise(res => setTimeout(res, ms));

async function fetchSucursalSales(sucId) {
  let all = [];
  let offset = 0;
  const limit = 50;
  while (true) {
    let res = null;
    let attempts = 0;
    while (attempts < 3 && !res) {
      try {
        res = await helpers.httpRequest({
          method: 'GET',
          url: 'https://erp.duxsoftware.com.ar/WSERP/rest/services/facturas',
          qs: {
            idEmpresa: ENTERPRISE_ID,
            idSucursal: sucId,
            fechaDesde: fDesde,
            fechaHasta: fHasta,
            limit,
            offset
          },
          headers: { authorization: DUX_TOKEN },
          json: true,
          timeout: 25000
        });
      } catch (e) {
        attempts++;
        if (attempts < 3) await delay(1500);
      }
    }
    const results = res?.results || [];
    all.push(...results);
    if (results.length < limit) break;
    offset += limit;
    await delay(300);
  }
  return all;
}

// Extraer facturas
const tomFacturas = await fetchSucursalSales(2);
const maschFacturas = await fetchSucursalSales(3);

// Procesar comprobantes
function processComprobantes(list, sucCode) {
  const byVend = {};
  let totBruto = 0, totNC = 0;

  list.forEach(inv => {
    if (inv.anulada_boolean === true || inv.anulada === 'S') return;
    const tipo = (inv.tipo_comp || '').toUpperCase();
    const total = Number(inv.total) || 0;
    const esNC = tipo.includes('CREDITO') || tipo.includes('NC');
    const vId = String(inv.id_vendedor || '');

    if (!byVend[vId]) byVend[vId] = { bruto: 0, nc: 0, neta: 0 };
    if (esNC) {
      byVend[vId].nc += total;
      totNC += total;
    } else {
      byVend[vId].bruto += total;
      totBruto += total;
    }
  });

  Object.keys(byVend).forEach(k => {
    byVend[k].neta = byVend[k].bruto - byVend[k].nc;
  });

  return { byVend, totBruto, totNC, totNeta: totBruto - totNC };
}

const tomProcessed = processComprobantes(tomFacturas, 'TOM');
const maschProcessed = processComprobantes(maschFacturas, 'MASCHWITZ');

return [{
  json: {
    periodo: targetPeriod,
    fDesde,
    fHasta,
    tomProcessed,
    maschProcessed
  }
}];

const prev = $('1. Extraer y Depurar Ventas Dux').first().json;
const objetivos = $input.all().map(i => i.json);

const periodo = prev.periodo;
const tom = prev.tomProcessed;
const masch = prev.maschProcessed;

// Obtener metas locales previstas
const objTomLocal = objetivos.find(o => o.sucursal_codigo === 'TOM' && o.colab_id === 'TOTAL_LOCAL') || {};
const objMaschLocal = objetivos.find(o => o.sucursal_codigo === 'MASCHWITZ' && o.colab_id === 'TOTAL_LOCAL') || {};

const metaTomN1 = Number(objTomLocal.objetivo_nivel_1) || 35000000;
const metaTomN2 = Number(objTomLocal.objetivo_nivel_2) || 42000000;
const metaMaschN1 = Number(objMaschLocal.objetivo_nivel_1) || 18000000;
const metaMaschN2 = Number(objMaschLocal.objetivo_nivel_2) || 21600000;

const liquidaciones = [];

// 1. LIQUIDAR TOM
const staffTom = [
  { vId: '1705102', colab_id: 'c-sofi', nombre: 'Sofía Barrientos', rol: 'Encargada' },
  { vId: '2907849', colab_id: 'c-esme', nombre: 'Esme Galarza', rol: 'Semi-Encargada' },
  { vId: '19950294', colab_id: 'c-cande', nombre: 'Candela Almiron', rol: 'Vendedora' },
  { vId: '19950328', colab_id: 'c-anto', nombre: 'Antonella Bustamante', rol: 'Vendedora' },
  { vId: '8662462', colab_id: 'c-martu', nombre: 'Martina Pinto', rol: 'Vendedora' }
];

staffTom.forEach(s => {
  const vData = tom.byVend[s.vId] || { bruto: 0, nc: 0, neta: 0 };
  const obj = objetivos.find(o => o.sucursal_codigo === 'TOM' && o.colab_id === s.colab_id) || {};
  const metaPrevista = Number(obj.objetivo_nivel_1) || 0;
  const metaN2 = Number(obj.objetivo_nivel_2) || 0;

  let porcAlcance = metaPrevista > 0 ? (vData.neta / metaPrevista) * 100 : 0;
  let porcComis = 0;
  let montoComis = 0;
  let montoPlusCaja = 0;
  let montoPozo = 0;
  let estadoPremio = 'Desempeño estándar';

  if (s.rol === 'Encargada') {
    // Encargada comisiona sobre el total local
    const alcLocal = (tom.totNeta / metaTomN1) * 100;
    porcAlcance = alcLocal;
    porcComis = tom.totNeta >= metaTomN2 ? 0.30 : (tom.totNeta >= metaTomN1 ? 0.20 : 0.10);
    montoComis = Math.round(tom.totNeta * (porcComis / 100));
  } else if (s.rol === 'Semi-Encargada') {
    // Escala propia s/ venta neta
    porcComis = vData.neta >= metaN2 ? 0.90 : (vData.neta >= metaPrevista ? 0.60 : 0.30);
    montoComis = Math.round(vData.neta * (porcComis / 100));
    // Plus Caja sobre el total local
    const porcPlus = tom.totNeta >= metaTomN2 ? 0.15 : (tom.totNeta >= metaTomN1 ? 0.10 : 0.05);
    montoPlusCaja = Math.round(tom.totNeta * (porcPlus / 100));
  } else {
    // Vendedora común
    porcComis = vData.neta >= metaN2 ? 0.90 : (vData.neta >= metaPrevista ? 0.60 : 0.30);
    montoComis = Math.round(vData.neta * (porcComis / 100));
  }

  if (porcAlcance >= 95) estadoPremio = `⭐ Estrella del Mes (${Math.round(porcAlcance)}% cumplimiento)`;

  liquidaciones.push({
    periodo,
    sucursal_codigo: 'TOM',
    colab_id: s.colab_id,
    nombre: s.nombre,
    rol: s.rol,
    venta_bruta: vData.bruto,
    notas_credito: vData.nc,
    venta_neta: vData.neta,
    objetivo_previsto: metaPrevista,
    porc_alcance: Math.round(porcAlcance * 100) / 100,
    porc_comision: porcComis,
    monto_comision: montoComis,
    monto_plus_caja: montoPlusCaja,
    monto_pozo: montoPozo,
    total_liquidado: montoComis + montoPlusCaja + montoPozo,
    estado_premio: estadoPremio,
    estado: 'borrador'
  });
});

// 2. LIQUIDAR MASCHWITZ
const staffMasch = [
  { vId: '11956305', colab_id: 'c-flavia', nombre: 'Flavia Gómez', rol: 'Encargada' },
  { vId: '5171913', colab_id: 'c-juli', nombre: 'Julieta Vera', rol: 'Vendedora' },
  { vId: '3988841', colab_id: 'c-cami', nombre: 'Camila Vera', rol: 'Vendedora' },
  { vId: '8662462', colab_id: 'c-martu_masch', nombre: 'Martina Pinto (Maschwitz)', rol: 'Vendedora' }
];

staffMasch.forEach(s => {
  const vData = masch.byVend[s.vId] || { bruto: 0, nc: 0, neta: 0 };
  const obj = objetivos.find(o => o.sucursal_codigo === 'MASCHWITZ' && o.colab_id === s.colab_id) || {};
  const metaPrevista = Number(obj.objetivo_nivel_1) || 0;
  const metaN2 = Number(obj.objetivo_nivel_2) || 0;

  let porcAlcance = metaPrevista > 0 ? (vData.neta / metaPrevista) * 100 : 0;
  let porcComis = 0;
  let montoComis = 0;
  let estadoPremio = 'Desempeño estándar';

  if (s.rol === 'Encargada') {
    const alcLocal = (masch.totNeta / metaMaschN1) * 100;
    porcAlcance = alcLocal;
    porcComis = masch.totNeta >= metaMaschN2 ? 0.30 : (masch.totNeta >= metaMaschN1 ? 0.20 : 0.10);
    montoComis = Math.round(masch.totNeta * (porcComis / 100));
  } else {
    porcComis = vData.neta >= metaN2 ? 0.90 : (vData.neta >= metaPrevista ? 0.60 : 0.30);
    montoComis = Math.round(vData.neta * (porcComis / 100));
  }

  if (porcAlcance >= 90) estadoPremio = `⭐ Estrella del Mes (${Math.round(porcAlcance)}% cumplimiento)`;

  liquidaciones.push({
    periodo,
    sucursal_codigo: 'MASCHWITZ',
    colab_id: s.colab_id,
    nombre: s.nombre,
    rol: s.rol,
    venta_bruta: vData.bruto,
    notas_credito: vData.nc,
    venta_neta: vData.neta,
    objetivo_previsto: metaPrevista,
    porc_alcance: Math.round(porcAlcance * 100) / 100,
    porc_comision: porcComis,
    monto_comision: montoComis,
    monto_plus_caja: 0,
    monto_pozo: 0,
    total_liquidado: montoComis,
    estado_premio: estadoPremio,
    estado: 'borrador'
  });
});

const totComisiones = liquidaciones.reduce((acc, l) => acc + l.total_liquidado, 0);

// Mensaje para Telegram
const msgTelegram = `📊 <b>CIERRE COMERCIAL DUX — ${periodo}</b>

` +
`🏢 <b>TOM:</b> $${tom.totNeta.toLocaleString('es-AR')} neto
` +
`🏢 <b>MASCHWITZ:</b> $${masch.totNeta.toLocaleString('es-AR')} neto
` +
`💰 <b>Total Comisiones a Liquidar:</b> $${totComisiones.toLocaleString('es-AR')}

` +
`🎯 <i>Los datos y nuevos objetivos quedaron guardados en BORRADOR.</i>
` +
`👉 <a href="https://juanoviedo1987-droid.github.io/NAZARIA-RRHH/">Entrá a la App para revisarlos y aprobar</a>`;

return [{
  json: {
    periodo,
    liquidaciones,
    msgTelegram
  }
}];
